"use client";

import { Box, MenuItem, TextField, Typography } from "@mui/material";
import { standardFieldSx } from "@/components/common/FormControls";

export type SearchSelectOption<TValue extends string> = {
  label: string;
  value: TValue;
};

export type SearchSelectFieldProps<TValue extends string> = {
  label: string;
  onChange: (value: TValue | "") => void;
  options: readonly SearchSelectOption<TValue>[];
  placeholder?: string;
  value: TValue | "";
};

export function SearchSelectField<TValue extends string>({
  label,
  onChange,
  options,
  placeholder = "전체",
  value,
}: SearchSelectFieldProps<TValue>) {
  return (
    <Box sx={{ display: "grid", gap: 0.75, alignSelf: "start" }}>
      <Typography sx={{ color: "text.secondary", fontSize: 13, fontWeight: 700, lineHeight: 1.2 }}>{label}</Typography>
      <TextField
        select
        fullWidth
        onChange={(event) => onChange(event.target.value as TValue | "")}
        placeholder={placeholder}
        size="small"
        sx={standardFieldSx}
        value={value}
      >
        <MenuItem value="">{placeholder}</MenuItem>
        {options.map((option) => (
          <MenuItem key={option.value} value={option.value}>
            {option.label}
          </MenuItem>
        ))}
      </TextField>
    </Box>
  );
}
